def backfill_variants(apps, schema_editor):
    """Create variants from existing posts, preserving publication IDs and status."""
    ContentPost = apps.get_model("publishing", "ContentPost")
    ContentPostVariant = apps.get_model("publishing", "ContentPostVariant")

    for post in ContentPost.objects.all():
        platforms = post.platforms or []

        for platform in platforms:
            if platform not in ["facebook", "instagram"]:
                continue

            variant_data = {
                "platform": platform,
                "caption": post.caption_for(platform)
                if hasattr(post, "caption_for")
                else post.caption,
                "media_urls": post.media_urls or [],
                "scheduled_at": post.scheduled_at,
                "status": post.status,
            }

            # Map publication IDs and metadata
            if platform == "facebook":
                if post.fb_post_id:
                    variant_data["publication_id"] = post.fb_post_id
                    variant_data["published_at"] = post.published_at
            elif platform == "instagram":
                if post.ig_media_id:
                    variant_data["publication_id"] = post.ig_media_id
                    variant_data["published_at"] = post.published_at
                if post.ig_container_id:
                    variant_data["metadata"] = {"ig_container_id": post.ig_container_id}

            # Create variant if it doesn't exist (idempotent)
            ContentPostVariant.objects.get_or_create(
                post=post,
                platform=platform,
                defaults=variant_data,
            )


